function App(): JSX.Element {
  // Initialize component state with useState
  const [count, setCount] = useState<number>(0);

  // Create a handler for synchronous increment
  const handleIncrement = () => {
    setCount(count + 1);
  };

  // Create a handler for asynchronous increment
  const handleIncrementAsync = () => {
    setTimeout(() => {
      setCount(count + 1);
    }, 1000);
  };

  // Return JSX structure here
  return (
    <div>
      <h1>Counter: {count}</h1>
      <button>Increment Now</button>
      <button>Increment After Delay</button>
    </div>
  );
}
